-- The Mandatory content spine card for France, New Zealand, Norway and
-- Slovakia. GENERATED by tools/mandatory-content-cards.mjs -- re-run the
-- tool rather than editing this file. Card content, researched from
-- primary sources where they could be read and from the tax authority's
-- own guidance where they could not, is in
-- tools/data/mandatory-content-cards.json.
--
-- New Zealand and Norway were already at the framework's five-card
-- ceiling, so the new card displaces one. Nothing is dropped without its
-- rows moving, and the merged card is retitled to describe what it now
-- holds rather than inheriting a title covering half of it.

-- ---- France: 4 -> 5 cards ----
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 4 FROM countries WHERE name_en = 'France';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'en', 'Mandatory content', '[["Standard particulars","Both parties, the invoice number and date, a description of the supply, and the net amount, VAT rate and VAT due for each rate."],["Four additions for 2026","A SIREN for supplier and customer, a delivery address where it differs, whether the supply is goods, services or both, and a VAT-on-debits mention."],["When the four bite","Invoices issued from 1 September 2026 for large and mid-sized firms, and from 1 September 2027 for micro and small ones."],["The legal list is not the file","What is transmitted is both narrower and broader than the legal list: no line description, but commercial-code mentions on top, fixed by arrêté."]]', 'Legifrance''s consolidated article already shows the four new mentions, under a banner reading "in force since 01/01/2025". The commencement rule is not in the code — it is in article 3 of décret 2022-1299.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Menciones estándar","Ambas partes, el número y la fecha de la factura, una descripción de la operación, y la base, el tipo de IVA y la cuota por cada tipo."],["Cuatro añadidos para 2026","Un SIREN para proveedor y cliente, la dirección de entrega si difiere, si la operación es de bienes, servicios o ambos, y la mención de IVA por débitos."],["Cuándo se aplican","A las facturas emitidas desde el 1 de septiembre de 2026 para las grandes y medianas empresas, y desde el 1 de septiembre de 2027 para las micro y pequeñas."],["La lista legal no es el fichero","Lo transmitido es más estrecho y más amplio que la lista legal: sin descripción de línea, pero con menciones del código de comercio, fijadas por arrêté."]]', 'El artículo consolidado de Legifrance ya muestra las cuatro nuevas menciones, bajo un aviso de «en vigor desde el 01/01/2025». La norma de entrada en vigor no está en el código, sino en el artículo 3 del décret 2022-1299.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'de', 'Pflichtangaben', '[["Standardangaben","Beide Parteien, Rechnungsnummer und -datum, eine Beschreibung der Leistung sowie Nettobetrag, Steuersatz und Steuerbetrag je Satz."],["Vier Ergänzungen ab 2026","Eine SIREN für Lieferant und Kunde, eine abweichende Lieferadresse, ob Waren, Dienstleistungen oder beides geliefert wird, und ein Hinweis zur Debitorenbesteuerung."],["Ab wann sie gelten","Für Rechnungen ab dem 1. September 2026 bei großen und mittleren Unternehmen, und ab dem 1. September 2027 bei Kleinst- und Kleinunternehmen."],["Die Rechtsliste ist nicht die Datei","Übermittelt wird zugleich weniger und mehr als die Rechtsliste: keine Positionsbeschreibung, dafür Angaben aus dem Handelsgesetzbuch, per Arrêté festgelegt."]]', 'Der konsolidierte Artikel auf Legifrance zeigt die vier neuen Angaben bereits, unter dem Hinweis „in Kraft seit 01.01.2025“. Die Inkrafttretensregel steht nicht im Gesetzbuch, sondern in Artikel 3 des Décret 2022-1299.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Mentions standard","Les deux parties, le numéro et la date de la facture, une description de l''opération, et le montant hors taxe, le taux et la TVA due par taux."],["Quatre ajouts pour 2026","Un SIREN pour le fournisseur et le client, l''adresse de livraison si elle diffère, la nature de l''opération, et la mention de l''option pour les débits."],["Quand elles s''appliquent","Aux factures émises à compter du 1er septembre 2026 pour les grandes et moyennes entreprises, et du 1er septembre 2027 pour les micro et petites."],["La liste légale n''est pas le fichier","Ce qui est transmis est à la fois plus étroit et plus large que la liste légale : pas de description de ligne, mais des mentions du code de commerce."]]', 'L''article consolidé sur Legifrance affiche déjà les quatre nouvelles mentions, sous un bandeau « en vigueur depuis le 01/01/2025 ». La règle d''entrée en vigueur n''est pas dans le code : elle est à l''article 3 du décret 2022-1299.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'France') AND d.section = 'file_format' AND d.sort_order = 4;

-- ---- New Zealand: 5 -> 5 cards ----
-- "No real-time reporting" folds into "Scope of the 2027 mandate", retitled "What the 2027 mandate covers", 3 rows.
UPDATE deep_dive_card_translations SET title = 'What the 2027 mandate covers', rows_json = '[["Applies to","Domestic trade invoices in NZD only"],["Excludes","International suppliers, cross-border invoicing"],["Tax reporting","GST continues via periodic returns"]]', note = 'If a New Zealand government contract has any cross-border element, check whether the specific invoice line falls inside this mandate. And unlike Ireland or France, no reporting layer is bolted on — this is an exchange format, not tax-administration reform.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'New Zealand' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET title = 'Qué cubre el mandato de 2027', rows_json = '[["Se aplica a","Facturas comerciales nacionales solo en NZD"],["Excluye","Proveedores internacionales, facturación transfronteriza"],["Reporte fiscal","El GST continúa mediante declaraciones periódicas"]]', note = 'Si un contrato con el gobierno neozelandés tiene algún elemento transfronterizo, compruebe si esa línea de factura concreta queda dentro del mandato. Y a diferencia de Irlanda o Francia, no se le añade ninguna capa de reporte: es un formato de intercambio, no una reforma de la administración tributaria.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'New Zealand' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET title = 'Was das Mandat von 2027 abdeckt', rows_json = '[["Gilt für","Nur inländische Handelsrechnungen in NZD"],["Ausgenommen","Internationale Lieferanten, grenzüberschreitende Rechnungsstellung"],["Steuermeldung","GST läuft weiterhin über periodische Erklärungen"]]', note = 'Enthält ein neuseeländischer Regierungsvertrag ein grenzüberschreitendes Element, prüfen Sie, ob die konkrete Rechnungszeile unter dieses Mandat fällt. Und anders als in Irland oder Frankreich kommt keine Meldeebene hinzu — es geht um ein Austauschformat, nicht um eine Reform der Steuerverwaltung.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'New Zealand' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET title = 'Ce que couvre le mandat de 2027', rows_json = '[["S''applique à","Factures commerciales nationales en NZD uniquement"],["Exclut","Fournisseurs internationaux, facturation transfrontalière"],["Déclaration fiscale","La GST continue via des déclarations périodiques"]]', note = 'Si un contrat avec le gouvernement néo-zélandais comporte un élément transfrontalier, vérifiez si la ligne de facture concernée relève de ce mandat. Et contrairement à l''Irlande ou à la France, aucune couche de déclaration n''y est greffée : c''est un format d''échange, pas une réforme de l''administration fiscale.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'New Zealand' AND d.section = 'file_format' AND d.sort_order = 2);
DELETE FROM deep_dive_card_translations WHERE card_id IN (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'New Zealand' AND d.section = 'file_format' AND d.sort_order = 3);
DELETE FROM deep_dive_cards WHERE section = 'file_format' AND country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND sort_order = 3;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 5 FROM countries WHERE name_en = 'New Zealand';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'en', 'Mandatory content', '[["No prescribed document","Since 1 April 2023 no tax-invoice document is required. The duty is to hold set GST details, which several records may carry between them."],["What the tiers change","At NZD 200 or less nothing need be given to the buyer. Above NZD 200 add the seller''s GST number; above NZD 1,000 add buyer identification."],["Buyer''s GST number","Rarely needed. Above NZD 1,000 give the buyer''s name and one identifier — an address, email or NZBN. Buyer-created records need both numbers."],["Peppol changes nothing","The content rule is format-neutral. A Peppol invoice can carry it, and adds no GST field of its own."]]', 'Read from Inland Revenue''s own guidance, not from the Act: legislation.govt.nz refused every request. The section numbers behind these rules are therefore uncited here.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Ningún documento prescrito","Desde el 1 de abril de 2023 no se exige un documento de factura fiscal. El deber es conservar ciertos datos de GST, que varios registros pueden repartirse."],["Qué cambian los tramos","Hasta 200 NZD no hay que entregar nada al comprador. Por encima de 200 NZD se añade el número de GST del vendedor; por encima de 1.000 NZD, la identificación del comprador."],["Número de GST del comprador","Rara vez necesario. Por encima de 1.000 NZD, el nombre del comprador y un identificador: dirección, correo o NZBN. Los registros creados por el comprador exigen ambos números."],["Peppol no cambia nada","La regla de contenido es neutral respecto al formato. Una factura Peppol puede llevarla, y no añade ningún campo de GST propio."]]', 'Tomado de la guía de Inland Revenue, no de la ley: legislation.govt.nz rechazó todas las peticiones. Por eso no se citan aquí los números de artículo.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'de', 'Pflichtangaben', '[["Kein vorgeschriebenes Dokument","Seit dem 1. April 2023 ist kein Steuerrechnungsdokument vorgeschrieben. Zu halten sind bestimmte GST-Angaben, die sich auf mehrere Belege verteilen dürfen."],["Was die Stufen ändern","Bis 200 NZD muss dem Käufer nichts ausgehändigt werden. Über 200 NZD kommt die GST-Nummer des Verkäufers hinzu, über 1.000 NZD die Identifikation des Käufers."],["GST-Nummer des Käufers","Selten erforderlich. Über 1.000 NZD Name des Käufers plus eine Kennung: Adresse, E-Mail oder NZBN. Vom Käufer erstellte Belege brauchen beide Nummern."],["Peppol ändert nichts","Die Inhaltsregel ist formatneutral. Eine Peppol-Rechnung kann sie tragen und fügt kein eigenes GST-Feld hinzu."]]', 'Aus der Anleitung von Inland Revenue entnommen, nicht aus dem Gesetz: legislation.govt.nz hat jede Anfrage abgewiesen. Die Paragraphennummern sind daher hier nicht zitiert.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Aucun document prescrit","Depuis le 1er avril 2023, aucun document de facture fiscale n''est exigé. L''obligation est de détenir certaines données de GST, que plusieurs pièces peuvent porter ensemble."],["Ce que changent les seuils","Jusqu''à 200 NZD, rien n''a à être remis à l''acheteur. Au-delà de 200 NZD s''ajoute le numéro de GST du vendeur ; au-delà de 1 000 NZD, l''identification de l''acheteur."],["Numéro de GST de l''acheteur","Rarement requis. Au-delà de 1 000 NZD, le nom de l''acheteur et un identifiant : adresse, courriel ou NZBN. Les pièces établies par l''acheteur exigent les deux numéros."],["Peppol ne change rien","La règle de contenu est neutre quant au format. Une facture Peppol peut la porter et n''ajoute aucun champ de GST propre."]]', 'Établi d''après les instructions d''Inland Revenue et non d''après la loi : legislation.govt.nz a refusé chaque requête. Les numéros d''article ne sont donc pas cités ici.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'New Zealand') AND d.section = 'file_format' AND d.sort_order = 5;

-- ---- Norway: 5 -> 5 cards ----
-- "Exemptions" folds into "Foreign entities", retitled "Who is in, and who is out", 4 rows.
UPDATE deep_dive_card_translations SET title = 'Who is in, and who is out', rows_json = '[["Scope","Same EHF requirements as Norwegian companies"],["Trigger","Local bookkeeping obligations under the Norwegian Bookkeeping Act"],["Small sole proprietorships","Turnover below NOK 50,000, if not VAT-registered"],["B2C","Explicitly excluded from the mandate"]]', note = 'A foreign entity holding Norwegian bookkeeping obligations gets no lighter version of the duty. A separate B2C e-receipts framework is being assessed by Skattedirektoratet — worth watching, but not part of this reform.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Norway' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET title = 'Quién entra y quién queda fuera', rows_json = '[["Alcance","Los mismos requisitos EHF que las empresas noruegas"],["Desencadenante","Obligaciones contables locales conforme a la Ley de Contabilidad noruega"],["Pequeñas empresas individuales","Facturación inferior a 50.000 NOK, si no están registradas a efectos de IVA"],["B2C","Explícitamente excluido del mandato"]]', note = 'Una entidad extranjera con obligaciones contables noruegas no obtiene una versión más ligera del deber. Skattedirektoratet evalúa por separado un marco de recibos electrónicos B2C: algo a vigilar, pero que no forma parte de esta reforma.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Norway' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET title = 'Wer erfasst ist und wer nicht', rows_json = '[["Umfang","Dieselben EHF-Anforderungen wie für norwegische Unternehmen"],["Auslöser","Lokale Buchführungspflichten nach dem norwegischen Buchführungsgesetz"],["Kleine Einzelunternehmen","Umsatz unter 50.000 NOK, sofern nicht umsatzsteuerpflichtig registriert"],["B2C","Ausdrücklich von der Pflicht ausgenommen"]]', note = 'Ein ausländisches Unternehmen mit norwegischen Buchführungspflichten erhält keine abgeschwächte Fassung der Pflicht. Skattedirektoratet prüft gesondert einen Rahmen für B2C-E-Belege — beobachtenswert, aber nicht Teil dieser Reform.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Norway' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET title = 'Qui est concerné, et qui ne l''est pas', rows_json = '[["Périmètre","Mêmes exigences EHF que pour les entreprises norvégiennes"],["Déclencheur","Obligations comptables locales au titre de la loi norvégienne sur la comptabilité"],["Petites entreprises individuelles","Chiffre d''affaires inférieur à 50 000 NOK, si non assujetties à la TVA"],["B2C","Explicitement exclu de l''obligation"]]', note = 'Une entité étrangère soumise à des obligations comptables norvégiennes n''obtient aucune version allégée de l''obligation. Skattedirektoratet évalue séparément un cadre de reçus électroniques B2C : à surveiller, mais hors de cette réforme.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Norway' AND d.section = 'file_format' AND d.sort_order = 2);
DELETE FROM deep_dive_card_translations WHERE card_id IN (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Norway' AND d.section = 'file_format' AND d.sort_order = 3);
DELETE FROM deep_dive_cards WHERE section = 'file_format' AND country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND sort_order = 3;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 5 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'en', 'Mandatory content', '[["Seven required elements","A number and date, both parties, what was supplied, when and where, the price and due date, and any VAT — the VAT stated in kroner."],["Seller''s number plus MVA","The seller gives its name and organisation number, suffixed MVA if VAT-registered. Norway has no separate VAT number."],["Buyer: name plus one ID","A name, and either an address or an organisation number. On reverse-charge sales the buyer''s organisation number is always required."],["Not the VAT Directive","The list comes from Norwegian bookkeeping law, so the Directive''s standard annotations do not apply as such. The format rules are EU-derived."]]', 'The content rule is bokføringsforskriften § 5-1-1 and the parties rule § 5-1-2 — not § 5-1, which is only the sub-chapter heading. Read from a government-hosted copy and Skatteetaten guidance; lovdata.no blocks automated access.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Siete elementos exigidos","Número y fecha, ambas partes, qué se entregó, cuándo y dónde, el precio y el vencimiento, y el IVA — expresado en coronas."],["Número del vendedor y MVA","El vendedor indica su nombre y número de organización, con el sufijo MVA si está registrado a efectos de IVA. Noruega no tiene un número de IVA aparte."],["Comprador: nombre y un ID","Un nombre, y una dirección o un número de organización. En ventas con inversión del sujeto pasivo el número de organización es siempre obligatorio."],["No es la Directiva del IVA","La lista procede de la ley contable noruega, por lo que las menciones estándar de la Directiva no se aplican como tales. El formato sí deriva de la UE."]]', 'La regla de contenido es bokføringsforskriften § 5-1-1 y la de las partes § 5-1-2 — no § 5-1, que es solo el encabezado del subcapítulo. Leído de una copia alojada por el gobierno y de la guía de Skatteetaten; lovdata.no bloquea el acceso automatizado.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'de', 'Pflichtangaben', '[["Sieben Pflichtangaben","Nummer und Datum, beide Parteien, was geliefert wurde, wann und wo, Preis und Fälligkeit sowie die Umsatzsteuer — in Kronen angegeben."],["Verkäufernummer plus MVA","Der Verkäufer nennt Namen und Organisationsnummer, mit dem Zusatz MVA bei Umsatzsteuerregistrierung. Norwegen hat keine gesonderte Umsatzsteuernummer."],["Käufer: Name plus eine Kennung","Ein Name sowie eine Adresse oder eine Organisationsnummer. Bei Umkehr der Steuerschuld ist die Organisationsnummer des Käufers stets erforderlich."],["Nicht die Mehrwertsteuerrichtlinie","Die Liste stammt aus dem norwegischen Buchführungsrecht, die Standardvermerke der Richtlinie gelten also nicht als solche. Die Formatregeln sind EU-abgeleitet."]]', 'Die Inhaltsregel ist bokføringsforskriften § 5-1-1, die Parteienregel § 5-1-2 — nicht § 5-1, das nur die Unterkapitelüberschrift ist. Gelesen aus einer staatlich gehosteten Kopie und der Skatteetaten-Anleitung; lovdata.no sperrt automatisierte Zugriffe.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Sept éléments exigés","Un numéro et une date, les deux parties, ce qui a été livré, quand et où, le prix et l''échéance, et la TVA — exprimée en couronnes."],["Numéro du vendeur plus MVA","Le vendeur indique son nom et son numéro d''organisation, suivi de MVA s''il est assujetti. La Norvège n''a pas de numéro de TVA distinct."],["Acheteur : nom plus un ID","Un nom, et soit une adresse soit un numéro d''organisation. En autoliquidation, le numéro d''organisation de l''acheteur est toujours exigé."],["Pas la directive TVA","La liste vient du droit comptable norvégien : les mentions standard de la directive ne s''appliquent donc pas comme telles. Le format, lui, dérive de l''UE."]]', 'La règle de contenu est bokføringsforskriften § 5-1-1 et celle des parties § 5-1-2 — pas § 5-1, qui n''est que l''intitulé du sous-chapitre. Lu depuis une copie hébergée par l''État et les instructions de Skatteetaten ; lovdata.no bloque l''accès automatisé.' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Norway') AND d.section = 'file_format' AND d.sort_order = 5;

